var t=`0737-misir-wat`;var n=`world-0737`;var s=`ET`;var a=`eastern-africa`;var r=4;var o=52;var g={en:`Misir Wat`,ua:`Місір ват`};var l={en:`Misir Wat is a Ethiopia classic prepared with yellow onion, niter kibbeh, garlic, ginger root. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Місір ват, страва кухні країни Ефіопія зі складниками: жовта цибуля, пряне масло нітер кіббе, часник, корінь імбиру. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 16 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 16 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:16,i:[[`yellow-onion`,210,`g`],[`niter-kibbeh`,50,`g`],[`garlic`,4,`clove`],[`ginger-root`,20,`g`],[`berbere`,22,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`red-lentils`,310,`g`],[`water`,850,`ml`],[`tomato-paste`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`injera`,4,`pcs`],[`table-salt`,null,`to_taste`]]}];var h={slug:t,id:n,country:`ET`,region:a,servings:4,minutes:52,title:g,text:l,steps:d};export{s as country,h as default,n as id,o as minutes,a as region,r as servings,t as slug,d as steps,l as text,g as title};